import { checkoutItems, freeDeliveryTotals, ratingMarkup, descriptionMarkup, mediaEditor, mediaEditorRows, readMediaEditor, customerReviews, adminReviews, reviewCards, reviewMore } from './product-extras.js';
const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:n%100?2:0}).format(n/100);
const paths={arrow:'M4 12h16m-6-6 6 6-6 6',bag:'M5 7h14l1 14H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',close:'m6 6 12 12M6 18 18 6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',truck:'M1 4h13v13H1zM14 9h5l3 4v4h-8M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0M20 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',leaf:'M20 3c-9-1-16 2-16 9a7 7 0 0 0 7 7c7 0 9-7 9-16ZM4 21 16 9',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Zm-4 10 3 3 5-6',box:'m12 2 10 5v10l-10 5-10-5V7l10-5Zm0 10 10-5M12 12 2 7m10 5v10M7 4.5l10 5',menu:'M3 6h18M3 12h18M3 18h18',check:'m5 12 4 4L19 6',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',logout:'M9 3H3v18h6m6-14 5 5-5 5M8 12h12',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.box}"/></svg>`;
const state={products:[],config:null,cart:[],admin:null,adminProducts:[],orders:[],adminSettings:null,sort:'featured',quantity:1,buyNow:null,adminReviews:null,announcementPaused:false};
try{state.cart=JSON.parse(localStorage.getItem('tscart_cart')||'[]').filter(i=>typeof i.id==='string'&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=10);}catch{}
try{const item=JSON.parse(sessionStorage.getItem('tscart_buy_now')||'null');if(item&&typeof item.id==='string'&&Number.isInteger(item.quantity)&&item.quantity>0&&item.quantity<=10)state.buyNow=item;}catch{}
function clearBuyNow(){state.buyNow=null;sessionStorage.removeItem('tscart_buy_now');}
async function api(path,{method='GET',data,headers={}}={}){
  const r=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:{...(method!=='GET'?{'X-Requested-With':'tscart'}:{}),...(data!==undefined?{'Content-Type':'application/json'}:{}),...headers},body:data===undefined?undefined:JSON.stringify(data)});
  let json;try{json=await r.json();}catch{throw new Error('The server returned an unexpected response ('+r.status+'). Restart the server and refresh the page.');}if(!r.ok)throw Object.assign(new Error(json.error||'Request failed ('+r.status+'). Please try again.'),{status:r.status});return json;
}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
const link=(url,text,cls='')=>`<a href="${url}" data-link class="${cls}">${text}</a>`;
const wordmark=()=>`<span class="wordmark">TSCART<span>HOME</span></span>`;
const categories=()=>[...new Set(state.products.map(p=>p.category))];
const image=(src,alt,cls='',lazy=true)=>`<img src="${esc(src?.startsWith('/assets/')?src+'?v=1.0.2':src||'/assets/placeholder.svg')}" alt="${esc(alt)}" class="${cls}" ${lazy?'loading="lazy"':''} decoding="async">`;
const badge=s=>`<span class="status ${esc(s)}">${esc(s.replaceAll('_',' '))}</span>`;
const qty=(id,value)=>`<div class="quantity"><button type="button" data-action="qty" data-id="${esc(id)}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${value}</span><button type="button" data-action="qty" data-id="${esc(id)}" data-delta="1" aria-label="Increase quantity">+</button></div>`;
const field=(name,label,value='',options={})=>`<label class="field ${options.wide?'wide':''}"><span>${label}${options.required?' *':''}</span>${options.area?`<textarea name="${name}" maxlength="${options.max||3000}" ${options.required?'required':''} ${options.min?`minlength="${options.min}"`: ''}>${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" type="${options.type||'text'}" ${options.required?'required':''} ${options.extra||''} maxlength="${options.max||200}" ${options.auto?`autocomplete="${options.auto}"`:''}>`}</label>`;
function cartItems(){return state.cart.map(i=>({...state.products.find(p=>p.id===i.id),quantity:i.quantity})).filter(i=>i.name);}
function totals(items=cartItems()){return freeDeliveryTotals(items);}
function saveCart(){localStorage.setItem('tscart_cart',JSON.stringify(state.cart));document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=state.cart.reduce((s,i)=>s+i.quantity,0));}
function announcement(text){const message=[text,'Free delivery on all orders'].filter(Boolean).join(' • ');const group=`<div class="announcement-group">${[1,2].map(()=>`<span>${esc(message)}</span><span aria-hidden="true">•</span>`).join('')}</div>`;return `<div class="announcement ${state.announcementPaused?'is-paused':''}"><span class="visually-hidden">${esc(message)}</span><div class="announcement-viewport" aria-hidden="true"><div class="announcement-track">${group}${group}</div></div><button type="button" class="announcement-toggle" data-action="toggle-announcement" aria-label="${state.announcementPaused?'Resume':'Pause'} announcement scrolling" aria-pressed="${state.announcementPaused}">${state.announcementPaused?'▶':'Ⅱ'}</button></div>`;}
function header(){const s=state.config.settings;return `${announcement(s.announcement)}<header class="header"><div class="container nav"><a href="/" data-link aria-label="TSCART home">${wordmark()}</a><nav class="navlinks" aria-label="Main navigation">${link('/shop','Shop all')}${link('/shop?category=Kitchen','Kitchen & dining')}${link('/shop?category=Living','Living')}${link('/shop?category=Bath','Bath & care')}</nav><div class="navtools"><button class="icon-button" data-action="search" aria-label="Search products">${icon('search')}</button><a href="/admin" data-link class="icon-button desktop-only" aria-label="Store admin">${icon('user')}</a><button class="icon-button" data-action="cart" aria-label="Open shopping bag">${icon('bag')}<small data-cart-count>${state.cart.reduce((s,i)=>s+i.quantity,0)}</small></button><button class="icon-button mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu')}</button></div></div></header>`;}
function footer(){return `<section class="closing"><div class="container"><div><h2>Good things. Everyday living.</h2><p>Little upgrades. A home that feels more like you.</p></div>${link('/shop','Find your everyday favourites '+icon('arrow'),'btn')}</div></section><footer class="footer"><div class="container"><div class="footer-grid"><div class="footer-intro">${link('/',wordmark())}<p>Thoughtfully chosen essentials for the spaces you live in, and the moments you live for.</p></div><div class="footer-col"><h3>Explore</h3>${link('/shop','All essentials')}${link('/shop?category=Kitchen','Kitchen & dining')}${link('/shop?category=Living','Living & décor')}${link('/shop?category=Bath','Bath & care')}</div><div class="footer-col"><h3>Here to help</h3>${link('/shipping','Shipping & delivery')}${link('/returns','Returns & exchanges')}${link('/contact','Contact us')}${link('/admin','Store admin')}</div><div class="footer-col"><h3>The finer details</h3>${link('/about','Our approach')}${link('/privacy','Privacy policy')}${link('/terms','Terms of service')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} TSCART. All rights reserved. &nbsp; Made for the everyday.</span><div class="footer-payments"><b>CASH ON DELIVERY</b><span>·</span><b>${state.config.onlinePayments?'Razorpay':'INR ₹'}</b>${icon('shield')}</div></div></div></footer>${state.config.mode==='demo'?'<div class="demo-note">Preview store · Sample catalogue and test COD orders · No real orders are dispatched</div>':''}`;}
function productCard(p){return `<article class="product-card"><div class="product-image">${link('/product/'+p.slug,image(p.image,p.name))}${p.badge?`<span class="product-badge">${esc(p.badge)}</span>`:''}<button class="quick-add" data-action="add" data-id="${p.id}" aria-label="Add ${esc(p.name)} to bag" ${!p.stock?'disabled':''}>${icon('plus')}</button></div><div class="product-meta"><small>${esc(p.category)} / ${esc(p.material)}</small><h3>${link('/product/'+p.slug,esc(p.name))}</h3><div class="product-bottom"><span class="product-price">${money(p.price)}</span><span class="fine">${p.stock?'':'Sold out'}</span></div>${ratingMarkup(p)}<button type="button" class="btn small full buy-now" data-action="buy-now" data-id="${p.id}" aria-label="Buy ${esc(p.name)} now" ${!p.stock?'disabled':''}>Buy now</button></div></article>`;}
function home(){return `<section class="container hero"><div class="hero-copy"><span class="eyebrow">The art of everyday living</span><h1>Small things.<br>Beautiful<br><em>everydays.</em></h1><p>A considered collection of home essentials.<br>For your rituals, your spaces, your kind of living.</p>${link('/shop','Explore the collection '+icon('arrow'),'btn')}<div class="hero-foot">${icon('shield')}A thoughtful home starts with the everyday.</div></div><div class="hero-image">${image('/assets/hero.jpg','Warm, sunlit living room with natural textures','',false)}<div class="hero-index">LIVING</div><div class="hero-caption"><span>THE CONSIDERED HOME</span><p>A little less ordinary.<br>A little more you.</p></div></div></section><div class="container trust-strip"><div>${icon('truck')}<div><strong>Delivered to your door</strong><span>Free delivery on all orders</span></div></div><div>${icon('bag')}<div><strong>Cash on delivery</strong><span>Pay when your order arrives</span></div></div><div>${icon('leaf')}<div><strong>Everyday, considered</strong><span>Useful pieces. Beautiful spaces.</span></div></div><div>${icon('heart')}<div><strong>A human touch</strong><span>We're here when you need us</span></div></div></div><section class="container section"><div class="section-head"><div><span class="eyebrow">A home, room by room</span><h2>Find your corner.</h2></div>${link('/shop','Discover all '+icon('arrow'),'text-link')}</div><div class="collections">${[['Kitchen','kitchen','Kitchen & dining','For the moments you share'],['Living','living','Living & décor','Make yourself at home'],['Bath','bath','Bath & care','Your daily moment of calm']].map(([cat,img,title,sub])=>`<a href="/shop?category=${cat}" data-link class="collection">${image('/assets/'+img+'.jpg',title)}<div class="collection-info"><div><h3>${title}</h3><small>${sub}</small></div><span class="round-arrow">${icon('arrow')}</span></div></a>`).join('')}</div></section><section class="products-section section"><div class="container"><div class="section-head"><div><span class="eyebrow">Objects to come home to</span><h2>The everyday edit.</h2></div>${link('/shop','Shop the edit '+icon('arrow'),'text-link')}</div><div class="product-grid">${state.products.filter(p=>p.featured).slice(0,4).map(productCard).join('')}</div></div></section><section class="container section philosophy"><div class="philosophy-image">${image('/assets/living.jpg','A quiet corner styled with natural home accessories')}</div><div class="philosophy-copy"><span class="eyebrow">A little more intention</span><h2>Your home.<br>Your kind of beautiful.</h2><p>We believe the things you use every day should feel a little special. The mug you reach for. The corner you curl up in. The details that make a space yours.</p><p>TSCART brings together simple, useful pieces that fit into your life — and make the everyday feel better.</p>${link('/about','Get to know TSCART '+icon('arrow'),'text-link')}<div class="values"><div><strong>Considered design</strong><span>Easy on the eyes.</span></div><div><strong>Everyday purpose</strong><span>At home in your life.</span></div></div></div></section>`;}
function shop(){const params=new URLSearchParams(location.search),category=params.get('category')||'All',search=params.get('q')||'';let products=state.products.filter(p=>(category==='All'||p.category===category)&&(!search||(p.name+' '+p.description+' '+p.category).toLowerCase().includes(search.toLowerCase())));if(state.sort==='low')products.sort((a,b)=>a.price-b.price);if(state.sort==='high')products.sort((a,b)=>b.price-a.price);return `<div class="container"><div class="page-head"><div class="breadcrumb">${link('/','Home')}<span>/</span>Collection</div><span class="eyebrow">For the way you live</span><h1>${search?'A little discovery.':category==='All'?'Everyday essentials.':esc(category)+', considered.'}</h1><p>${search?`Results for “${esc(search)}”`:'Useful, beautiful things for the place you call home.'}</p></div><div class="shop-toolbar"><div class="chips">${['All',...categories()].map(c=>link('/shop'+(c==='All'?'':'?category='+encodeURIComponent(c)),esc(c),'chip '+(c===category?'active':''))).join('')}</div><label class="fine">${products.length} pieces &nbsp; <select id="sort" aria-label="Sort products"><option value="featured" ${state.sort==='featured'?'selected':''}>The considered edit</option><option value="low" ${state.sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${state.sort==='high'?'selected':''}>Price: high to low</option></select></label></div><div class="shop-grid">${products.length?`<div class="product-grid">${products.map(productCard).join('')}</div>`:'<div class="empty"><h2>No pieces found.</h2><p>Try a different search or explore the full collection.</p>'+link('/shop','Explore all essentials','btn outline')+'</div>'}</div></div>`;}
async function productPage(slug){const p=state.products.find(p=>p.slug===slug);if(!p)return notFound();const reviewData=await api('/api/products/'+p.id+'/reviews');return `<div class="container"><div class="page-head"><div class="breadcrumb">${link('/','Home')}<span>/</span>${link('/shop?category='+encodeURIComponent(p.category),esc(p.category))}<span>/</span>${esc(p.name)}</div></div><div class="product-detail"><div>${image(p.image,p.name,'detail-main',false)}${p.images.length>1?`<div class="thumbs">${p.images.map((img,i)=>`<button data-action="image" data-src="${esc(img)}" aria-label="View image ${i+1}">${image(img,p.name)}</button>`).join('')}</div>`:''}</div><div class="detail-copy"><span class="eyebrow">${esc(p.category)} / The considered collection</span><h1>${esc(p.name)}</h1><a href="#reviews" class="rating-jump">${ratingMarkup({reviewCount:reviewData.total,ratingAverage:reviewData.ratingAverage})}</a><p class="fine">${esc(p.material)}</p><div class="price">${money(p.price)}</div><span class="fine">Product price includes applicable taxes. Free delivery.</span><p class="detail-description">${esc(p.description)}</p>${descriptionMarkup(p.descriptionMedia||[])}<span class="stock">${p.stock?'Available for your home':'Currently sold out'}</span><div class="purchase-row">${qty('detail',state.quantity)}<button class="btn" data-action="add-detail" data-id="${p.id}" ${!p.stock?'disabled':''}>Add to bag ${icon('bag')}</button><button type="button" class="btn buy-now-detail" data-action="buy-now" data-id="${p.id}" data-quantity="detail" ${!p.stock?'disabled':''}>Buy now ${icon('arrow')}</button></div><div class="purchase-perks"><span>${icon('truck')}Free delivery on all orders</span><span>${icon('shield')}Cash on delivery</span></div><details open><summary>The details</summary><p>${esc(p.details||p.description)}</p></details><details><summary>Delivery & returns</summary><p>${esc(state.config.settings.deliveryText)}</p><p>${esc(state.config.settings.returnsText)}</p></details><details><summary>Need a hand?</summary><p>${link('/contact','Get in touch with the TSCART team.')}</p></details></div></div>${customerReviews(p,reviewData)}<section class="section"><div class="section-head"><h2>A little more to love.</h2>${link('/shop','Explore all '+icon('arrow'),'text-link')}</div><div class="product-grid">${state.products.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div></section></div>`;}
function summary(items=cartItems(),t=totals()){return `<div class="order-summary"><h2>A few good things.</h2>${items.map(i=>`<div class="summary-item">${image(i.image,i.name)}<div class="info"><h3>${esc(i.name)}</h3><small>Quantity ${i.quantity}</small></div><b>${money(i.price*i.quantity)}</b></div>`).join('')}<div class="total-row"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="total-row"><span>Delivery</span><span>${t.shipping?money(t.shipping):'Free'}</span></div><div class="total-row grand"><span>Total</span><strong>${money(t.total)}</strong></div><p class="fine">All prices in INR. No extra COD fee.</p></div>`;}
function checkout(){const items=checkoutItems(state.products,state.cart,state.buyNow);if(!items.length)return `<section class="container section empty"><h1>Your bag is taking a breather.</h1><p>Find something that feels at home.</p>${link('/shop','Explore the collection','btn')}</section>`;return `<div class="container"><div class="page-head"><div class="breadcrumb">${link('/shop','Collection')}<span>/</span><span>Secure checkout</span></div><h1>Almost home.</h1><p>A few details, and we'll take it from here.</p></div><div class="checkout"><form id="checkout-form">${state.config.mode==='demo'?'<div class="notice">This is a preview. COD checkout creates a test order; nothing will be shipped.</div>':''}<section class="form-section"><h2><span>01</span> Where should we send it?</h2><div class="form-grid">${field('name','Full name','',{required:true,auto:'name',wide:true,max:80})}${field('phone','Mobile number','',{required:true,type:'tel',auto:'tel-national',max:16,extra:'inputmode="tel" placeholder="10-digit Indian mobile"'})}${field('email','Email (optional)','',{type:'email',auto:'email',max:150})}${field('line1','House number & street','',{required:true,auto:'address-line1',wide:true,max:180})}${field('line2','Apartment, area or landmark (optional)','',{auto:'address-line2',wide:true,max:120})}${field('city','City','',{required:true,auto:'address-level2',max:70})}${field('state','State / union territory','',{required:true,auto:'address-level1',max:70})}${field('pincode','PIN code','',{required:true,auto:'postal-code',max:6,extra:'inputmode="numeric" pattern="[1-9][0-9]{5}"'})}<label class="field"><span>Country</span><input value="India" disabled></label>${field('notes','Delivery notes (optional)','',{area:true,wide:true,max:250})}</div></section><section class="form-section"><h2><span>02</span> Your preferred way to pay</h2><label class="payment-choice"><input type="radio" name="paymentMethod" value="cod" ${state.config.onlinePayments?'':'checked'}><div><strong>Cash on delivery</strong><p>Pay the delivery partner when it arrives.</p></div></label><label class="payment-choice"><input type="radio" name="paymentMethod" value="razorpay" ${state.config.onlinePayments?'checked':''} ${!state.config.onlinePayments?'disabled':''}><div><strong>Pay online with Razorpay</strong><p>${state.config.onlinePayments?(state.config.testPayments?'Test payment · no real money moves':'UPI, cards, netbanking and more.'):'Online payments will be available once the store connects Razorpay.'}</p></div><span class="tag">${state.config.onlinePayments?'RECOMMENDED':'COMING SOON'}</span></label></section><label class="check-label"><input type="checkbox" name="consent" required><span>I agree to the <a href="/terms" target="_blank" rel="noopener">terms</a> and <a href="/privacy" target="_blank" rel="noopener">privacy policy</a>. My name, contact details, address and order details will be used by TSCART’s fulfilment team to process and deliver this order.</span></label><div class="form-error" role="alert"></div><button class="btn full" type="submit">${state.config.mode==='demo'?'Place test order':'Place order'} ${icon('arrow')}</button><p class="fine center space-top">${icon('shield')} Your payment details are handled by Razorpay when you pay online.</p></form>${summary(items,totals(items))}</div></div>`;}
function notFound(){return `<div class="container section empty"><span class="eyebrow">A little off the beaten path</span><h1>Nothing here, just yet.</h1><p>Let's find something for your home.</p>${link('/shop','Back to the collection','btn')}</div>`;}
function policies(path){const s=state.config.settings;const content={
  '/about':['A little more intention.',`TSCART is built around a simple idea: the things you use every day should feel good to live with. We bring together useful home essentials with a calm, considered point of view.\n\nFrom your first cup of the morning to the corner you settle into at night, we’re here for the small details that make a home feel yours.`,[['The collection','Explore kitchen essentials, living accessories, bath pieces and simple storage. Our catalogue evolves as we find new pieces for the everyday.'],['The way we work','Some pieces are fulfilled by our supply partners. TSCART remains your point of contact for order support, delivery queries and returns.']]],
  '/shipping':['On its way home.',s.deliveryText,[['Delivery charges',`Delivery is free on all orders. There is no minimum order value. We currently accept Indian delivery addresses, subject to serviceability.`],['Cash on delivery','COD orders are payable to the delivery partner. We may contact you to confirm the address and delivery availability. There is no additional COD fee.'],['Order updates','Keep your confirmation link to check the order status and tracking information. Contact the team with your order number if you need help. Delivery timings can vary by destination and supplier.']]],
  '/returns':['A little help, if you need it.',s.returnsText,[['Contact us first','Please contact TSCART with your order number, the item concerned and a description of the issue. For a damaged or incorrect item, include clear photographs so we can help.'],['Payment refunds','Where a refund is approved, the team will arrange it through the original payment method where possible. COD refund arrangements will be agreed with you. Do not send an item back without return instructions.']]],
  '/privacy':['Your details, thoughtfully handled.','We collect your name, mobile number, optional email, delivery address, order contents and delivery notes to accept, process and fulfil your order.',[['Order fulfilment','Your order details are stored by TSCART and accessible to authorised administrators in the store admin panel. This includes your name, phone number, optional email, delivery address, item names, quantities, prices, total and delivery notes. Details are shared with suppliers and delivery partners as needed to fulfil your order.'],['Online payments','If you choose online payment, Razorpay processes the payment and receives relevant checkout details. TSCART stores payment references and statuses, but does not receive or store your card number, CVV, UPI PIN or bank password.'],['Customer reviews','If you submit a review, your display name, star rating, review text and posting date are publicly visible on the product page. Do not include contact information or delivery addresses in reviews.'],['Browser storage','Your shopping bag is kept in local storage. Private order access links are kept in session storage. An essential, secure-session cookie is used for admin sign-in. This package does not include advertising trackers.'],['Retention & your requests','Order records are retained for fulfilment, customer support and applicable recordkeeping needs. Contact the store to request access, correction or deletion where applicable. Avoid putting sensitive personal information in delivery notes.']]],
  '/terms':['The finer details.','By ordering from TSCART, you agree to provide accurate contact and delivery information and to review the product, price and delivery terms before checkout.',[['Products & orders','Product colours may vary across screens. Check each product description before ordering. Receipt of an order does not guarantee delivery where stock, address or supplier availability prevents fulfilment. We will contact you if an order cannot be fulfilled.'],['Pricing & payment','Prices are listed in Indian rupees and include applicable product taxes. Delivery charges are displayed separately before order placement. COD payment is due on delivery. Online orders are confirmed after the payment is captured by Razorpay.'],['Cancellations & assistance','Contact us promptly with your order number for cancellation requests. Orders already dispatched may need to follow the returns process. Refunds, where applicable, are arranged by the store team.'],['Store operator',`${s.businessName}${s.businessAddress?'\n'+s.businessAddress:''}\n${s.supportEmail||'Contact details are being configured.'}\n${s.supportPhone}`]]],
  '/contact':['We’re here to help.','Questions about a piece, your order or your delivery? Get in touch with the TSCART team.',[['Call the team',s.supportPhone],['Email',s.supportEmail||'Our support email is being set up. Please call us in the meantime.'],['Our address',s.businessAddress||'The store is completing its business details.'],['About your order','Please include your order number when contacting us. Keep your private confirmation link safe — it provides access to your order details.']]]
};const c=content[path];if(!c)return notFound();return `<article class="container policy"><span class="eyebrow">TSCART / ${path.slice(1)}</span><h1>${c[0]}</h1><p>${esc(c[1])}</p>${c[2].map(([h,p])=>`<h2>${h}</h2><p>${esc(p)}</p>`).join('')}${link('/shop','Back to the collection '+icon('arrow'),'text-link')}</article>`;}
let previousFocus;
function modal(html,drawer=false){previousFocus=document.activeElement;$('#overlay').innerHTML=`<div class="overlay-backdrop" data-backdrop><section class="${drawer?'drawer':'modal'}" role="dialog" aria-modal="true" aria-label="${drawer?'Shopping bag':'TSCART dialog'}">${html}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('#overlay button, #overlay input, #overlay a')?.focus());}
function closeModal(){if(!$('#overlay').innerHTML)return;$('#overlay').innerHTML='';document.body.style.overflow='';previousFocus?.focus();}
function cart(){const items=cartItems(),t=totals();modal(`<div class="drawer-head"><h2>Your good things.</h2><button class="icon-button" data-action="close" aria-label="Close shopping bag">${icon('close')}</button></div><div class="drawer-body">${items.length?`<p class="fine">Free delivery on every order.</p>${items.map(i=>`<div class="cart-item">${image(i.image,i.name)}<div class="info"><h3>${link('/product/'+i.slug,esc(i.name))}</h3><p>${money(i.price)}</p>${qty(i.id,i.quantity)}<button class="remove" data-action="remove" data-id="${i.id}">Remove</button></div></div>`).join('')}`:`<div class="empty"><h2>A little room for something good.</h2><p>Your bag is currently empty.</p>${link('/shop','Explore the collection','btn')}</div>`}</div>${items.length?`<div class="drawer-foot"><div class="total-row"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><p class="fine">Free delivery. COD available.</p>${link('/checkout','Continue to checkout '+icon('arrow'),'btn full')}</div>`:''}`,true);}
function searchModal(){modal(`<div class="modal-head"><h2>Find your everyday.</h2><button class="icon-button" data-action="close" aria-label="Close search">${icon('close')}</button></div><form id="search-form"><div class="search-field">${icon('search')}<input id="search-input" name="q" placeholder="Try a mug, a basket, a little calm…" aria-label="Search the collection" autofocus></div></form><div id="search-results" class="search-results">${searchResults('')}</div>`);$('#search-input').focus();}
function searchResults(query){const products=state.products.filter(p=>(p.name+' '+p.category).toLowerCase().includes(query.toLowerCase())).slice(0,5);return products.length?products.map(p=>link('/product/'+p.slug,image(p.image,p.name)+`<div><strong>${esc(p.name)}</strong><p>${esc(p.category)} · ${money(p.price)}</p></div>`)).join(''):'<p>No pieces found. Try another word.</p>';}
async function receipt(id){const token=sessionStorage.getItem('tscart_order_'+id);if(!token)return `<div class="container section empty"><h2>This order link is private.</h2><p>Open your saved confirmation link, or contact the team with your order number.</p>${link('/contact','Contact TSCART','btn')}</div>`;const {order:o}=await api('/api/orders/'+id,{headers:{'X-Order-Token':token}});const success=['confirmed','processing','shipped','delivered'].includes(o.status);return `<div class="container receipt"><div class="receipt-head"><div class="receipt-check">${icon(success?'check':'clock')}</div><h1>${o.demo?'Your test order is in.':success?'Good things are on their way.':o.status==='cancelled'?'This order was cancelled.':o.status==='needs_review'?'Your payment needs our attention.':'Your order is waiting.'}</h1><p>${o.paymentStatus==='cod_due'?'Pay on delivery. We’ll take it from here.':o.paymentStatus==='paid'?'Your payment has been received.':'Check your order details below.'}</p><strong>${esc(o.id)}</strong> &nbsp; ${badge(o.status)}</div>${o.demo?'<div class="notice">Demo order only. No payment was taken and no item will ship.</div>':''}<div class="receipt-box"><div class="receipt-grid"><div><h3>Delivery details</h3><p>${esc([o.customer.name,o.customer.line1,o.customer.line2,o.customer.city+', '+o.customer.state+' '+o.customer.pincode,'+91 '+o.customer.phone].filter(Boolean).join('\n'))}</p></div><div><h3>Payment & tracking</h3><p>${o.paymentMethod==='cod'?'Cash on delivery':'Razorpay'}\n${esc(o.paymentStatus.replaceAll('_',' '))}\n${esc(o.tracking||'Tracking will appear once the team updates your shipment.')}</p></div></div></div>${summary(o.items,o)}<div class="admin-actions space-top">${o.status==='awaiting_payment'?`<button class="btn" data-action="pay" data-id="${o.id}">Continue payment ${icon('arrow')}</button>`:''}<button class="btn outline" data-action="refresh">Refresh status</button><button class="btn outline" data-action="copy-order" data-id="${o.id}">Copy private order link</button>${link('/shop','Back to the collection','btn outline')}</div><p class="fine space-top">Keep your order link private. It provides access to the delivery and contact details for this order.</p></div>`;}

async function adminPage(path,requestId=renderId){
  let admin;
  try{admin=await api('/api/admin/session');}catch(e){if(e.status!==401)throw e;admin=null;}
  if(requestId!==renderId)return '';
  state.admin=admin;
  if(!state.admin)return `<div class="container"><form id="login-form" class="admin-login"><span class="eyebrow">The space behind the store</span><h1>Welcome back.</h1><p>Sign in to manage your TSCART store.</p>${field('email','Admin email','',{required:true,type:'email',auto:'username'})}${field('password','Password','',{required:true,type:'password',auto:'current-password'})}<div class="form-error" role="alert"></div><button class="btn full" type="submit">Sign in ${icon('arrow')}</button></form></div>`;
  const tab=path.split('/')[2]||'overview';const edit=path.split('/')[3];
  const results=await Promise.all([api('/api/admin/products'),api('/api/admin/orders'),api('/api/admin/settings')]);
  if(requestId!==renderId)return '';
  state.adminProducts=results[0].products;state.orders=results[1].orders;state.adminSettings=results[2];
  const reviews=tab==='products'&&edit&&edit!=='new'?await api('/api/admin/products/'+edit+'/reviews'):{reviews:[],total:0,ratingAverage:0,nextOffset:null};
  if(requestId!==renderId)return '';
  state.adminReviews=reviews;
  return `<div class="container admin-layout"><aside class="admin-nav"><h2>Store studio.</h2>${[['overview','Overview','grid'],['products','Products','box'],['orders','Orders','bag'],['settings','Settings','settings']].map(([id,label,i])=>link('/admin/'+id,icon(i)+label,tab===id?'active':'')).join('')}<a href="#" data-action="logout">${icon('logout')} Sign out</a></aside><div class="admin-content">${state.admin.mustChange?`<div class="notice">Your starter login is active. ${link('/admin/settings','Set a new password')} before opening the store for real orders.</div>`:''}${tab==='products'?(edit?productEditor(edit):adminProducts()):tab==='orders'?(edit?adminOrder(edit):adminOrders()):tab==='settings'?adminSettings():adminOverview()}</div></div>`;
}
function adminOverview(){const o=state.orders.filter(o=>!o.demo);const paid=o.filter(o=>['paid','cod_collected'].includes(o.paymentStatus)).reduce((s,o)=>s+o.total,0);return `<div class="admin-title"><div><h1>A little overview.</h1><p>Your store, at a glance. ${state.config.mode==='demo'?'You’re in demo mode.':''}</p></div>${link('/admin/products/new','New product '+icon('plus'),'btn small')}</div><div class="stats"><div class="stat"><span>Collected revenue · recent orders</span><b>${money(paid)}</b><span>Captured online + collected COD</span></div><div class="stat"><span>Live orders</span><b>${o.length}</b><span>Excludes demo orders</span></div><div class="stat"><span>Published products</span><b>${state.adminProducts.filter(p=>p.active).length}</b><span>Visible in the collection</span></div><div class="stat"><span>Needs attention</span><b>${state.orders.filter(o=>o.status==='needs_review').length}</b><span>Payments to review</span></div></div><div class="section-head space-top"><h2 style="font-size:29px">Recent orders</h2>${link('/admin/orders','View orders '+icon('arrow'),'text-link')}</div>${orderTable(state.orders.slice(0,8))}<div class="notice space-top">All orders and customer delivery details are saved in this admin. Review delivery, prices, policies and sample products before launch. Totals show the most recent 500 orders.</div>`;}
function orderTable(orders){return orders.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Payment</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.id)}${o.demo?'<br><span class="fine">Demo</span>':''}</td><td>${esc(o.customer.name)}<br><span class="fine">${new Date(o.created).toLocaleDateString('en-IN')}</span></td><td>${money(o.total)}</td><td>${badge(o.status)}</td><td>${badge(o.paymentStatus)}</td><td>${link('/admin/orders/'+o.id,'View →','text-link')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>A clean slate.</h2><p>Your orders will appear here after checkout.</p></div>';}
function adminOrders(){return `<div class="admin-title"><div><h1>Orders.</h1><p>Review delivery details, fulfilment and payments.</p></div><button class="btn outline small" data-action="export-orders">Export CSV</button></div><div class="search-field">${icon('search')}<input id="order-search" placeholder="Find an order, name or phone number" aria-label="Search orders"></div><div id="orders-table">${orderTable(state.orders)}</div>`;}
function deleteProductButton(p,small=false){return `<button type="button" class="btn outline danger ${small?'small':''}" data-action="delete-product" data-id="${p.id}" aria-label="Delete ${esc(p.name)}">${small?'Delete':'Delete product'}</button>`;}
function adminProducts(){return `<div class="admin-title"><div><h1>The collection.</h1><p>Make room for your next everyday favourite.</p></div>${link('/admin/products/new','Add product '+icon('plus'),'btn small')}</div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Available stock</th><th>Visibility</th><th></th></tr></thead><tbody>${state.adminProducts.map(p=>`<tr><td><div class="table-product">${image(p.image,p.name)}<div>${esc(p.name)}<br><span class="fine">${esc(p.category)}</span></div></div></td><td>${money(p.price)}</td><td>${p.stock}</td><td>${badge(p.active?'published':'archived')}</td><td><div class="admin-actions">${link('/admin/products/'+p.id,'Edit →','text-link')}${deleteProductButton(p,true)}</div></td></tr>`).join('')}</tbody></table></div>`;}
function productEditor(id){const p=id==='new'?{name:'',slug:'',price:0,category:'Living',stock:0,description:'',images:[],active:true,featured:false}:state.adminProducts.find(p=>p.id===id);if(!p)return notFound();return `<div class="admin-title"><div><h1>${id==='new'?'Something new.':'Make it your own.'}</h1><p>Prices are entered in rupees. Stock is available stock, excluding reserved orders.</p></div>${link('/admin/products','Back to products','text-link')}</div><form id="product-form" data-id="${id}"><div class="form-error product-form-error" role="alert" tabindex="-1"></div><div class="admin-card"><div class="form-grid">${field('name','Product name',p.name,{required:true,wide:true,max:90})}${field('slug','URL slug',p.slug,{required:true,extra:'pattern="[a-z0-9]+(-[a-z0-9]+)*"',max:100})}${field('category','Category',p.category,{required:true,max:40,extra:'list="category-list"'})}<datalist id="category-list">${['Living','Kitchen','Bath','Organisation'].map(x=>`<option value="${x}">`).join('')}</datalist>${field('price','Price (₹)',p.price/100,{required:true,type:'number',extra:'min="1" max="1000000" step="0.01"'})}${field('stock','Available stock',p.stock,{required:true,type:'number',extra:'min="0" max="1000000" step="1"'})}${field('material','Material / finish',p.material||'',{max:100})}${field('badge','Small product label (optional)',p.badge||'',{max:40})}${field('description','Description',p.description,{required:true,area:true,wide:true})}${field('details','Specifications & care',p.details||'',{area:true,wide:true})}</div></div>${mediaEditor(p.descriptionMedia||[])}<div class="admin-card"><h2>Let it be seen.</h2><p>Upload JPG, PNG or WebP images (5 MB each), or paste HTTPS image URLs, one per line. The first image is the cover. Up to 8 images.</p><input id="image-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple aria-label="Upload product photos"><div class="image-previews" id="image-previews">${p.images.map(x=>image(x,'Product preview')).join('')}</div>${field('images','Product image URLs',p.images.join('\n'),{required:true,area:true,wide:true,max:10000})}</div><div class="admin-card"><label class="check-label"><input name="active" type="checkbox" ${p.active?'checked':''}>Published in the storefront (uncheck to save a draft)</label><label class="check-label"><input name="featured" type="checkbox" ${p.featured?'checked':''}>Feature in the homepage edit (first 4 featured products)</label></div><div class="save-bar"><button class="btn" type="submit">Save product ${icon('check')}</button>${id!=='new'?`<button type="button" class="btn outline" data-action="archive" data-id="${p.id}">Archive product</button>${deleteProductButton(p)}`:''}</div></form>${id!=='new'?adminReviews(p,state.adminReviews):''}`;}
function adminOrder(id){const o=state.orders.find(o=>o.id===id);if(!o)return notFound();const states={awaiting_payment:['awaiting_payment','cancelled'],confirmed:['confirmed','processing','cancelled'],processing:['processing','shipped','cancelled'],shipped:['shipped','delivered'],delivered:['delivered'],cancelled:['cancelled'],needs_review:['needs_review']};return `<div class="admin-title"><div><h1>${esc(o.id)}</h1><p>${new Date(o.created).toLocaleString('en-IN')} ${o.demo?'· Demo order':''}</p></div>${link('/admin/orders','All orders','text-link')}</div>${o.status==='needs_review'?'<div class="notice">Payment arrived after cancellation. Do not dispatch automatically. Review stock and refund this payment from the Razorpay dashboard if it cannot be fulfilled.</div>':''}<div class="admin-card"><div class="receipt-grid"><div><h3>Customer & delivery</h3><p>${esc([o.customer.name,'+91 '+o.customer.phone,o.customer.email,o.customer.line1,o.customer.line2,o.customer.city+', '+o.customer.state+' '+o.customer.pincode].filter(Boolean).join(' · '))}</p><p>Delivery notes: ${esc(o.customer.notes||'None')}</p></div><div><h3>Payment</h3>${badge(o.paymentStatus)}<p>${money(o.total)} · ${o.paymentMethod==='cod'?'Cash on delivery':'Razorpay'}</p><code>${esc(o.gatewayId||'')}</code><br><code>${esc(o.paymentId||'')}</code></div></div><div class="admin-order-items">${o.items.map(i=>`<div><span>${esc(i.name)} × ${i.quantity}</span><span>${money(i.price*i.quantity)}</span></div>`).join('')}<div><span>Delivery</span><span>${money(o.shipping)}</span></div><div><strong>Total</strong><strong>${money(o.total)}</strong></div></div></div><form id="order-form" data-id="${id}" class="admin-card"><h2>Fulfilment</h2><div class="form-grid"><label class="field"><span>Status</span><select name="status">${states[o.status].map(s=>`<option ${s===o.status?'selected':''} value="${s}">${s.replaceAll('_',' ')}</option>`).join('')}</select></label>${field('tracking','Courier & tracking reference',o.tracking||'',{max:200})}</div>${o.paymentMethod==='cod'?'<label class="check-label"><input type="checkbox" name="codCollected">COD money has been collected (only after delivery)</label>':'<label class="check-label"><input type="checkbox" name="gatewayChecked">Before cancelling, I checked Razorpay for authorised/captured payments and will arrange any required refund. Cancellation does not refund money.</label>'}<div class="form-error" role="alert"></div><button class="btn small space-top" type="submit">Save fulfilment</button></form>${o.paymentMethod==='razorpay'?`<form id="reconcile-form" data-id="${id}" class="admin-card"><h2>Payment reconciliation</h2><p>Fetch the latest provider status. If order creation was interrupted, find the Razorpay order with receipt ${esc(id)} and enter its ID. Never create another payment for the same customer charge.</p>${field('gatewayId','Razorpay order ID',o.gatewayId||'',{required:true})}<div class="form-error" role="alert"></div><button class="btn small space-top">Reconcile payment</button></form>`:''}`;}
function adminSettings(){const {settings:s,integrations:i,webhookUrl}=state.adminSettings;return `<div class="admin-title"><div><h1>Make it TSCART.</h1><p>Your store details, delivery rules and connections.</p></div></div><form id="settings-form" class="admin-card"><h2>Store & delivery</h2><div class="form-grid">${field('businessName','Business name',s.businessName,{required:true,max:120})}${field('supportEmail','Support email',s.supportEmail,{type:'email',max:150})}${field('supportPhone','Support phone',s.supportPhone,{max:25})}${field('announcement','Announcement bar',s.announcement,{max:180})}${field('businessAddress','Business address',s.businessAddress,{area:true,wide:true,max:500})}<p class="field wide">Delivery is free on every order.</p>${field('deliveryText','Delivery policy / timelines',s.deliveryText,{area:true,wide:true,max:2000})}${field('returnsText','Returns policy',s.returnsText,{area:true,wide:true,max:3000})}</div><div class="form-error" role="alert"></div><button class="btn small space-top">Save store settings</button></form><div class="admin-card"><h2>Razorpay</h2>${badge(i.razorpay?'configured':'waiting_setup')}<p>Mode: ${esc(i.razorpayMode)}. Add the Key ID, Key Secret and webhook secret to your server’s environment.</p><p>Webhook endpoint:</p><code>${esc(webhookUrl)}</code><p>Subscribe to payment.captured and order.paid. Enable automatic capture. See docs/RAZORPAY.md.</p></div><form id="password-form" class="admin-card space-top"><h2>Admin password</h2><p>You are signed in as ${esc(state.admin.email)}. Changing the password signs out all admin sessions.</p><div class="form-grid">${field('currentPassword','Current password','',{required:true,type:'password',auto:'current-password'})}${field('password','New password (12+ characters)','',{required:true,type:'password',auto:'new-password',extra:'minlength="12"'})}</div><div class="form-error" role="alert"></div><button class="btn small space-top">Change password</button></form><div class="notice">Store mode is set in .env. Use STORE_MODE=live only after replacing the sample catalogue, reviewing policies and completing setup. Keep data/ backed up and use persistent hosting.</div>`;}

let renderId=0;
async function render(){const n=++renderId;closeModal();let html;try{const path=location.pathname;if(path.startsWith('/admin'))html=await adminPage(path,n);else if(path.startsWith('/order/'))html=await receipt(path.split('/')[2]);else html=path==='/'?home():path==='/shop'?shop():path.startsWith('/product/')?await productPage(path.split('/')[2]):path==='/checkout'?checkout():policies(path);if(n!==renderId)return;$('#app').innerHTML=header()+`<main id="main">${html}</main>`+(path.startsWith('/admin')?'':footer());document.title=(path.startsWith('/admin')?'Store studio':path==='/checkout'?'Checkout':path==='/shop'?'The collection':'Beautifully everyday')+' — TSCART';}catch(e){if(n===renderId)$('#app').innerHTML=header()+`<main id="main" class="container section empty"><h2>A moment, please.</h2><p>${esc(e.message)}</p><button class="btn" data-action="refresh">Try again</button></main>`;}}
function navigate(url){const target=new URL(url,location.origin);if(target.origin!==location.origin){location.href=url;return;}if(target.pathname!=='/checkout')clearBuyNow();history.pushState({},'',target.pathname+target.search+target.hash);state.quantity=1;render();window.scrollTo(0,0);}
function add(id,quantity=1){const p=state.products.find(p=>p.id===id);if(!p)return;const old=state.cart.find(i=>i.id===id);const next=(old?.quantity||0)+quantity;if(next>Math.min(10,p.stock))return toast('That quantity isn’t available.');if(!old&&state.cart.length>=12)return toast('Your bag can hold up to 12 different pieces.');if(old)old.quantity=next;else state.cart.push({id,quantity});saveCart();toast(p.name+' added to your bag.');}
async function loadRazorpay(){if(window.Razorpay)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=resolve;s.onerror=()=>{s.remove();reject(new Error('Unable to load Razorpay. Please check your connection and try again.'));};document.head.append(s);});}
async function pay(id){const token=sessionStorage.getItem('tscart_order_'+id),headers={'X-Order-Token':token};const {order}=await api('/api/orders/'+id,{headers});await loadRazorpay();const p=await api('/api/orders/'+id+'/payment',{method:'POST',headers,data:{}});const rzp=new window.Razorpay({key:p.key,amount:p.amount,currency:p.currency,order_id:p.orderId,name:'TSCART',description:'Home essentials · '+id,image:location.origin+'/assets/mark.svg',prefill:{name:order.customer.name,email:order.customer.email,contact:'+91'+order.customer.phone},theme:{color:'#3f4d3a'},handler:async response=>{try{await api('/api/orders/'+id+'/verify',{method:'POST',headers,data:response});toast('Payment verified. Thank you.');}catch(e){toast(e.message+' Refresh the order status before paying again.');}await render();},modal:{ondismiss:()=>toast('Your order is saved. You can resume payment here.')}});rzp.on('payment.failed',()=>toast('Payment was not completed. You can retry in Razorpay or return to your order.'));rzp.open();}
document.addEventListener('click',async e=>{
  const a=e.target.closest('a[data-link]');if(a&&e.button===0&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();if(new URL(a.href).pathname==='/checkout')clearBuyNow();navigate(a.href);return;}
  if(e.target.hasAttribute('data-backdrop'))return closeModal();
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;e.preventDefault();
  try{
    if(action==='toggle-announcement'){state.announcementPaused=!state.announcementPaused;b.closest('.announcement').classList.toggle('is-paused',state.announcementPaused);b.setAttribute('aria-pressed',String(state.announcementPaused));b.setAttribute('aria-label',(state.announcementPaused?'Resume':'Pause')+' announcement scrolling');b.textContent=state.announcementPaused?'▶':'Ⅱ';}
    if(action==='close')closeModal();if(action==='cart')cart();if(action==='search')searchModal();if(action==='add')add(id);
    if(action==='add-detail'){add(id,state.quantity);cart();}
    if(action==='buy-now'){
      const product=state.products.find(p=>p.id===id),quantity=b.dataset.quantity==='detail'?state.quantity:1;
      if(!product||!product.stock||quantity>Math.min(10,product.stock))throw new Error('That quantity isn’t available.');
      state.buyNow={id,quantity};sessionStorage.setItem('tscart_buy_now',JSON.stringify(state.buyNow));navigate('/checkout');
    }
    if(action==='media-add-url'||action==='media-up'||action==='media-down'||action==='media-remove'){
      const list=$('#description-media-list'),items=readMediaEditor(list),index=Number(b.dataset.index);
      if(action==='media-add-url'){
        if(items.length>=10)throw new Error('Use up to 10 description media files.');
        const url=$('#description-media-url').value.trim();let parsed;try{parsed=new URL(url);}catch{throw new Error('Enter a direct HTTPS media URL.');}
        if(parsed.protocol!=='https:'||parsed.username||parsed.password)throw new Error('Enter a direct HTTPS media URL.');
        items.push({type:$('#description-media-type').value,url,caption:''});$('#description-media-url').value='';
      }else if(action==='media-remove')items.splice(index,1);
      else {const next=index+(action==='media-up'?-1:1);if(next>=0&&next<items.length)[items[index],items[next]]=[items[next],items[index]];}
      list.innerHTML=mediaEditorRows(items);
    }
    if(action==='more-reviews'){
      b.disabled=true;const admin=b.dataset.admin==='true';
      const data=await api('/api/'+(admin?'admin/':'')+'products/'+id+'/reviews?offset='+b.dataset.offset);
      $('#'+(admin?'admin':'public')+'-review-list').insertAdjacentHTML('beforeend',reviewCards(data.reviews,admin));
      $('#'+(admin?'admin':'public')+'-review-more').innerHTML=reviewMore(id,data,admin);
    }
    if(action==='delete-review'){
      if(!confirm('Delete this customer review? This cannot be undone.'))return;
      b.disabled=true;await api('/api/admin/reviews/'+id,{method:'DELETE',data:{}});
      const productId=$('#product-form').dataset.id,data=await api('/api/admin/products/'+productId+'/reviews');
      $('#admin-reviews').outerHTML=adminReviews({id:productId},data);
      state.products=(await api('/api/products')).products;toast('Review deleted.');
    }
    if(action==='qty'){if(id==='detail'){const p=state.products.find(p=>'/product/'+p.slug===location.pathname);state.quantity=Math.max(1,Math.min(10,p.stock,state.quantity+Number(b.dataset.delta)));b.parentElement.querySelector('span').textContent=state.quantity;}else{const item=state.cart.find(i=>i.id===id),p=state.products.find(p=>p.id===id);if(item){item.quantity=Math.max(1,Math.min(10,p.stock,item.quantity+Number(b.dataset.delta)));saveCart();cart();}}}
    if(action==='remove'){state.cart=state.cart.filter(i=>i.id!==id);saveCart();cart();}
    if(action==='image')$('.detail-main').src=b.dataset.src;
    if(action==='menu')modal(`<div class="modal-head">${wordmark()}<button class="icon-button" data-action="close" aria-label="Close menu">${icon('close')}</button></div><div class="footer-col">${link('/shop','Shop all essentials')}${categories().map(c=>link('/shop?category='+encodeURIComponent(c),esc(c))).join('')}${link('/about','Our approach')}${link('/contact','Contact us')}${link('/admin','Store admin')}</div>`);
    if(action==='refresh'){state.products=(await api('/api/products')).products;await render();}
    if(action==='pay'){b.disabled=true;await pay(id);b.disabled=false;}
    if(action==='copy-order'){const url=location.origin+'/order/'+id+'#token='+sessionStorage.getItem('tscart_order_'+id);try{await navigator.clipboard.writeText(url);toast('Private order link copied.');}catch{modal(`<div class="modal-head"><h2>Your private link.</h2><button class="icon-button" data-action="close" aria-label="Close">${icon('close')}</button></div><p class="fine">Copy this link and keep it private.</p><textarea readonly>${esc(url)}</textarea>`);}}
    if(action==='logout'){await api('/api/admin/logout',{method:'POST',data:{}});state.admin=null;navigate('/admin');}
    if(action==='archive'||action==='delete-product'){
      const product=state.adminProducts.find(p=>p.id===id);
      if(!product)throw new Error('Product not found. Reload the product list.');
      const deleting=action==='delete-product';
      modal(`<div class="modal-head"><h2>${deleting?'Delete this product?':'Archive this product?'}</h2><button type="button" class="icon-button" data-action="close" aria-label="Cancel">${icon('close')}</button></div><p><strong>${esc(product.name)}</strong></p><p>${deleting?'This permanently removes the product and its reviews. Existing orders and their item details are preserved.':'This hides the product from the storefront. You can publish it again later.'}</p><div class="form-error" role="alert"></div><div class="admin-actions"><button type="button" class="btn outline" data-action="close">Cancel</button><button type="button" class="btn ${deleting?'outline danger':''}" data-action="confirm-product-removal" data-id="${esc(id)}" data-permanent="${deleting}">${deleting?'Delete product':'Archive product'}</button></div>`);
    }
    if(action==='confirm-product-removal'){
      const deleting=b.dataset.permanent==='true',dialog=b.closest('[role=dialog]'),error=dialog.querySelector('.form-error'),label=b.textContent;
      b.disabled=true;error.textContent='';b.textContent=deleting?'Deleting…':'Archiving…';
      try{
        await api('/api/admin/products/'+id+(deleting?'/permanent':''),{method:'DELETE',data:{}});
        if(deleting){
          const [publicCatalogue,adminCatalogue]=await Promise.all([api('/api/products'),api('/api/admin/products')]);
          if(publicCatalogue.products.some(p=>p.id===id)||adminCatalogue.products.some(p=>p.id===id)){
            throw new Error('The delete request succeeded, but this server returned the product again. TSCART needs one shared, persistent DATA_DIR and a single always-on Node instance; separate or temporary SQLite instances can show old products.');
          }
          state.products=publicCatalogue.products;state.adminProducts=adminCatalogue.products;
        }else{
          state.products=state.products.filter(p=>p.id!==id);
          state.adminProducts=state.adminProducts.map(p=>p.id===id?{...p,active:false}:p);
        }
        state.cart=state.cart.filter(i=>i.id!==id);saveCart();
        closeModal();toast(deleting?'Product deleted. Existing orders are preserved.':'Product archived.');navigate('/admin/products');
      }catch(err){if(dialog.isConnected){error.textContent=err.message;error.scrollIntoView({block:'nearest'});}else toast(err.message);b.disabled=false;b.textContent=label;}
    }
    if(action==='export-orders'){const clean=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'").replaceAll('"','""')+'"';const rows=[['Order','Created','Name','Phone','Email','Address','Items','Total INR','Status','Payment','Demo'],...state.orders.map(o=>[o.id,new Date(o.created).toISOString(),o.customer.name,o.customer.phone,o.customer.email,[o.customer.line1,o.customer.line2,o.customer.city,o.customer.state,o.customer.pincode].filter(Boolean).join(', '),o.items.map(i=>i.name+' x'+i.quantity).join('; '),o.total/100,o.status,o.paymentStatus,o.demo])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(clean).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='tscart-orders.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  }catch(error){toast(error.message);b.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.id==='search-input')$('#search-results').innerHTML=searchResults(e.target.value);if(e.target.id==='order-search'){const q=e.target.value.toLowerCase();$('#orders-table').innerHTML=orderTable(state.orders.filter(o=>(o.id+' '+o.customer.name+' '+o.customer.phone).toLowerCase().includes(q)));}if(e.target.name==='name'&&e.target.closest('#product-form')?.dataset.id==='new'){const slug=$('#product-form [name=slug]');if(!slug.dataset.manual)slug.value=e.target.value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}if(e.target.name==='slug')e.target.dataset.manual='1';});
document.addEventListener('change',async e=>{if(e.target.id==='sort'){state.sort=e.target.value;render();}if(e.target.id==='image-upload'){const el=e.target,save=el.closest('form').querySelector('button[type=submit]');el.disabled=true;save.disabled=true;try{const urls=$('#product-form [name=images]');const current=urls.value.split('\n').filter(Boolean);const files=[...el.files];if(current.length+files.length>8)throw new Error('Choose up to 8 images in total.');for(const file of files){if(file.size>5*1024*1024)throw new Error('Each image must be under 5 MB.');const r=await fetch('/api/admin/upload',{method:'POST',headers:{'X-Requested-With':'tscart','Content-Type':file.type},body:file});const json=await r.json();if(!r.ok)throw new Error(json.error);current.push(json.url);urls.value=current.join('\n');$('#image-previews').innerHTML=current.map(x=>image(x,'Product preview')).join('');}toast('Images uploaded. Save the product to publish them.');}catch(err){toast(err.message);}finally{el.disabled=false;el.value='';save.disabled=$('#description-media-upload').disabled;}}});
document.addEventListener('invalid',e=>{const form=e.target.closest('#product-form');if(!form)return;const error=$('.form-error',form),label=e.target.closest('.field')?.querySelector('span')?.textContent||'Product field';error.textContent=label+': '+e.target.validationMessage;toast(error.textContent);},true);
document.addEventListener('submit',async e=>{
  const form=e.target;if(!form.matches('#checkout-form,#login-form,#product-form,#settings-form,#password-form,#order-form,#reconcile-form,#search-form,#review-form'))return;e.preventDefault();const values=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type=submit]')||form.querySelector('button:not([type])');const error=$('.form-error',form);if(error)error.textContent='';if(button)button.disabled=true;
  try{
    if(form.id==='search-form'){navigate('/shop?q='+encodeURIComponent(values.q));return;}
    if(form.id==='login-form'){state.admin=await api('/api/admin/login',{method:'POST',data:values});navigate('/admin');}
    if(form.id==='checkout-form'){const usingBuyNow=!!state.buyNow;
      const payload={customer:Object.fromEntries(Object.entries(values).filter(([k])=>!['paymentMethod','consent'].includes(k))),paymentMethod:values.paymentMethod,consent:values.consent==='on',items:state.buyNow?[state.buyNow]:state.cart};
      const signature=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(payload))))).map(x=>x.toString(16).padStart(2,'0')).join('');let request;try{request=JSON.parse(sessionStorage.getItem('tscart_checkout'));}catch{}if(!request||request.signature!==signature)request={signature,key:crypto.randomUUID()};sessionStorage.setItem('tscart_checkout',JSON.stringify(request));
      const result=await api('/api/orders',{method:'POST',data:payload,headers:{'Idempotency-Key':request.key}});sessionStorage.setItem('tscart_order_'+result.order.id,result.token);sessionStorage.removeItem('tscart_checkout');if(usingBuyNow)clearBuyNow();else state.cart=[];saveCart();state.products=(await api('/api/products')).products;navigate('/order/'+result.order.id);if(payload.paymentMethod==='razorpay')await pay(result.order.id);
    }
    if(form.id==='product-form'){if($('#description-media-upload').disabled||$('#image-upload').disabled)throw new Error('Wait for the media upload to finish.');const id=form.dataset.id;const saved=await api('/api/admin/products',{method:'POST',data:{...values,...(id!=='new'?{id,expectedStock:state.adminProducts.find(p=>p.id===id).stock}:{}),price:Math.round(Number(values.price)*100),stock:Number(values.stock),descriptionMedia:readMediaEditor($('#description-media-list')),images:values.images.split('\n').map(s=>s.trim()).filter(Boolean),active:values.active==='on',featured:values.featured==='on'}});state.products=(await api('/api/products')).products;toast(saved.product.active?'Product saved and published.':'Product saved as a draft. Enable Published to show it in the shop.');navigate('/admin/products');}
    if(form.id==='settings-form'){await api('/api/admin/settings',{method:'POST',data:values});state.config=await api('/api/config');toast('Store settings saved.');render();}
    if(form.id==='review-form'){
      const payload={name:values.name,rating:Number(values.rating),body:values.body},signature=JSON.stringify(payload);
      if(form.dataset.signature!==signature){form.dataset.signature=signature;form.dataset.requestKey=crypto.randomUUID();}
      await api('/api/products/'+form.dataset.id+'/reviews',{method:'POST',data:payload,headers:{'Idempotency-Key':form.dataset.requestKey}});
      state.products=(await api('/api/products')).products;toast('Thank you. Your review has been posted.');await render();
    }
    if(form.id==='password-form'){await api('/api/admin/password',{method:'POST',data:values});state.admin=null;toast('Password changed. Please sign in again.');navigate('/admin');}
    if(form.id==='order-form'){await api('/api/admin/orders/'+form.dataset.id,{method:'POST',data:{...values,codCollected:values.codCollected==='on',gatewayChecked:values.gatewayChecked==='on'}});toast('Order updated.');render();}
    if(form.id==='reconcile-form'){await api('/api/admin/orders/'+form.dataset.id+'/reconcile',{method:'POST',data:values});toast('Payment status checked.');render();}
  }catch(err){if(error&&form.isConnected){error.textContent=err.message;error.scrollIntoView({block:'center'});if(form.id==='product-form')error.focus();}else toast(err.message);}finally{if(button)button.disabled=false;}
});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.src.endsWith('/assets/placeholder.svg'))e.target.src='/assets/placeholder.svg';},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#overlay').innerHTML){const focus=[...$('#overlay').querySelectorAll('a,button,input,select,textarea,[tabindex]')].filter(el=>!el.disabled);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('popstate',()=>{if(location.pathname!=='/checkout')clearBuyNow();render();});
async function boot(){try{if(location.pathname!=='/checkout')clearBuyNow();if(location.pathname.startsWith('/order/')&&location.hash.startsWith('#token=')){const id=location.pathname.split('/')[2],token=location.hash.slice(7);if(/^[a-f0-9]{64}$/.test(token))sessionStorage.setItem('tscart_order_'+id,token);history.replaceState({},'',location.pathname);}const [config,products]=await Promise.all([api('/api/config'),api('/api/products')]);state.config=config;state.products=products.products;state.cart=state.cart.filter(i=>state.products.some(p=>p.id===i.id));saveCart();await render();}catch{$('#app').innerHTML='<main class="container section empty"><h1>A moment, please.</h1><p>The store could not connect. Refresh the page to try again.</p></main>';}}
boot();

document.addEventListener('change',async e=>{
  if(e.target.matches('#review-form input[name=rating]'))document.querySelectorAll('.rating-option').forEach(label=>{const filled=Number(label.querySelector('input').value)<=Number(e.target.value);label.querySelector('span').textContent=filled?'★':'☆';});
  if(e.target.id!=='description-media-upload')return;
  const el=e.target,form=el.closest('form'),save=form.querySelector('button[type=submit]'),list=$('#description-media-list');el.disabled=true;save.disabled=true;
  try{
    const items=readMediaEditor(list),files=[...el.files];if(items.length+files.length>10)throw new Error('Use up to 10 description media files.');
    for(const file of files){
      const limit=file.type.startsWith('image/')?5:20;if(file.size>limit*1024*1024)throw new Error(`Each ${file.type.startsWith('image/')?'image':'video or audio file'} must be ${limit} MB or smaller.`);
      const response=await fetch('/api/admin/description-media',{method:'POST',headers:{'X-Requested-With':'tscart','Content-Type':file.type||'application/octet-stream'},body:file});
      const result=await response.json();if(!response.ok)throw new Error(result.error||'Upload failed.');
      items.push({type:result.type,url:result.url,caption:''});list.innerHTML=mediaEditorRows(items);
    }
    toast('Description media uploaded. Save the product to publish it.');
  }catch(error){toast(error.message);}finally{el.disabled=false;el.value='';save.disabled=$('#image-upload').disabled;}
});
